add(609,'single','Меньшая сторона параллелограмма равна 29 см. Перпендикуляр из пересечения диагоналей к большей стороне делит её на 33 см и12 см. Найдите площадь.','900 см².',[
 R('Чему равна большая сторона?','AD =33 +12 =45 см. Пусть O — пересечение диагоналей, OH ⟂AD, M — середина AD. Тогда AM =22,5 см и MH =|33 −22,5| =10,5 см. Если AH =12, получается то же MH.','Середина и длины отрезков.',7),
 R('Почему OM равен половине меньшей стороны?','O — середина AC. В треугольнике ADC отрезок OM соединяет середины AC иAD, поэтому OM =CD/2 =29/2 =14,5 см.','Средняя линия треугольника, доказанная в задаче484; CD =AB.',[48,49]),
 R('Как найти OH?','В прямоугольном OMH: OH² =OM² −MH² =14,5² −10,5² =(14,5 −10,5)(14,5 +10,5) =100. Поэтому OH =10 см.','Теорема Пифагора.',60),
 R('Как найти площадь?','Расстояние между основаниями равно 2OH =20 см, поскольку O — середина диагонали. Значит S =45·20 =900 см².','Симметрия параллелограмма и формула площади.',[53,57])],p,v,[f,g,f,f],checks=para_checks()+[equal(('A','B'),('C','D')),equal(('A','M'),('M','D')),ratio('O','M','A','B',.5),ratio('O','H','A','D',2/9)])
