add(615,'single','Через D на стороне BC треугольника ABC проведены DE ∥AC иDF ∥AB, где E на AB, F на AC. Докажите, что треугольники CDE иBDF равновелики.','S(CDE) =S(ADE) =S(ADF) =S(BDF).',[
 R('Какая фигура образована около A?','AEDF — параллелограмм: AE ∥DF иAF ∥DE. Его диагональ AD делит его на два равных, значит равновеликих треугольника ADE иADF.','Свойства параллелограмма.',[48,54]),
 R('Почему CDE иADE равновелики?','У них общее основание DE, а вершины A иC лежат на прямой AC, параллельной DE. Следовательно их высоты к DE одинаковы, и площади равны.','Треугольники с одним основанием между параллельными прямыми.',58),
 R('Почему BDF иADF равновелики?','Они имеют общее основание DF, а вершины A иB лежат на параллельной DF прямой AB. Значит и их площади равны. Получаем требуемую цепочку равенств.','Та же формула площади.',58),
 R('Что с концами BC?','Доказательство с невырожденными фигурами относится к внутренней D. В концах BC соответствующие треугольники вырождаются и обе сравниваемые площади равны нулю.','Проверка граничных положений.',54)],p,v,[f,f,f,f],checks=[par('D','E','A','C'),par('D','F','A','B')])
