add(616,'в','В трапеции ABCD с боковыми сторонами AB иCD диагонали пересекаются в O. Докажите, что OA·OB =OC·OD.','OA·OB =OC·OD.',[
 R('Какие площади равны?','По части б S(AOB) =S(COD): из равновеликих ABD иACD вычли AOD.','Треугольники между параллельными прямыми и сложение площадей.',[54,58]),
 R('Как связать площади с нужными произведениями?','Углы AOB иCOD равны как вертикальные. По теореме об отношении площадей треугольников с равным углом: S(AOB)/S(COD) =(OA·OB)/(OC·OD).','Отношение площадей при равном угле.',58),
 R('Что следует из отношения1?','Левая часть равна1. Все четыре отрезка положительны, поэтому OA·OB =OC·OD.','Умножение пропорции.',58)],p,v,[fd,g,g],checks=[ang('A','O','B',math.degrees(math.acos(sum((p['A'][i]-p['O'][i])*(p['B'][i]-p['O'][i]) for i in (0,1))/(dist(p['A'],p['O'])*dist(p['B'],p['O'])))))])
