# Exact cell coordinates reread from figures218 and219. One cell side is1cm.
def grid(points):
 p=deepcopy(points);lines=[]
 for x in range(12):
  a,b='_gx'+str(x)+'a','_gx'+str(x)+'b';p[a]=[x,0];p[b]=[x,8];lines.append([a,b])
 for y in range(9):
  a,b='_gy'+str(y)+'a','_gy'+str(y)+'b';p[a]=[0,y];p[b]=[11,y];lines.append([a,b])
 return p,lines

def bounding(p,names):
 xmin=min(p[a][0] for a in names);xmax=max(p[a][0] for a in names);ymin=min(p[a][1] for a in names);ymax=max(p[a][1] for a in names)
 p.update(_L=[xmin,ymin],_R=[xmax,ymin],_T=[xmax,ymax],_U=[xmin,ymax])
 return poly(['_L','_R','_T','_U'])

