def selfcheck():
 from check_models import validate
 assert set(B.ex)==set(range(605,640))
 assert sum(len(x['parts']) for x in B.ex.values())==49
 for entry in B.models:
  errors=validate(entry['model']);assert not errors,(entry['number'],entry['part'],errors)
 checks=0
 def check(n,part,names,want):
  nonlocal checks
  got=area(RAW[n,part],names);assert math.isclose(got,want,rel_tol=1e-10,abs_tol=1e-10),(n,part,got,want);checks+=1
 for n,part,names,want in [
  (607,'single','ABCD',140/3),(608,'single','ABCD',24),(609,'single','ABCD',900),
  (611,'single','ABE',12),(611,'single','ADF',12),(611,'single','AECF',12),
  (612,'single','ABC',2*math.sqrt(6)),(615,'single','CDE',7.2),(615,'single','BDF',7.2),
  (618,'single','ABCD',216),(619,'single','ABCD',540),(620,'а','ABC',100*math.sqrt(3)),(620,'б','ABC',18),
  (621,'single','ABC',320),(622,'single','ABCD',84),(623,'а','ABCD',243),(623,'б','ABCD',529),
  (624,'single','ABCD',49),(625,'single','ABCD',49),(627,'single','BDM',48),(628,'single','ADPE',math.sqrt(2)-1),
  (629,'single','ABC',30),(630,'single','ABC',84),(630,'single','BCM',30),(631,'single','ABCD',2*math.sqrt(5)/5),
  (632,'single','ABCD',48),(633,'single','ABO',30),(633,'single','CDO',30),(634,'single','ABCD',80),
  (635,'single','ABC',64*math.sqrt(3)),(636,'single','ABKM',19.14)]:check(n,part,names,want)
 for part,want in zip('абвгд',[24,24,9,12,21]):check(638,part,'ABC',want)
 for part,want in zip('абвгд',[18,32,27,19.5,23.5]):check(639,part,'ABCDEF' if part=='д' else 'ABCD',want)
 p=RAW[617,'single'];assert math.isclose(area(p,'ABCD')/2,area(p,'BCFE'),rel_tol=1e-12);checks+=1
 p=RAW[616,'в'];assert math.isclose(dist(p['O'],p['A'])*dist(p['O'],p['B']),dist(p['O'],p['C'])*dist(p['O'],p['D']),rel_tol=1e-12);checks+=1
 for x in [-7,-2,0,2,6,8,14]:
  a=[0,0];b=[x,4];c=[6,0];h=[x,0]
  assert math.isclose(dist(b,c)**2,dist(a,b)**2+dist(a,c)**2-2*6*x,rel_tol=1e-12);checks+=1
 # Independent determinant checks of constant-distance sums, including obtuse apex.
 for height in [.5,1,3,5,8]:
  a=[0,height];b=[-4,0];c=[4,0]
  for x in [-4,-3.5,-1,0,2.5,4]:
   m=[x,0];got=dist(m,foot(m,a,b))+dist(m,foot(m,a,c));want=8*height/dist(a,b)
   assert math.isclose(got,want,rel_tol=1e-11,abs_tol=1e-11),(height,x,got,want);checks+=1
 print('CHAPTER07_C_AUTHOR_SELF_CHECKS',checks,'area/identity cases;',len(B.models),'models valid')
if __name__=='__main__':
 selfcheck()
 # The source grid is unlettered; labelled reasoning views omit its dense background.
 for entry in B.models:
  if entry['number'] in [638,639]:
   for name,view in entry['model']['views'].items():
    if name in ['neutral','step-1']:view['points']=[]
    else:view['dashSegments']=[segment for segment in view.get('dashSegments',[]) if not any(name.startswith(('_gx','_gy')) for name in segment)]
   entry['model']['description']='Сторона клетки — 1 см. Первый вид показывает исходную сетку без букв; следующие виды выделяют обозначения и вспомогательные построения для расчёта.'
 def tidy(value):
  if isinstance(value,str):
   value=re.sub(r'(?<=[А-Яа-яЁё])(?=[0-9A-Za-z])',' ',value)
   return re.sub(r'(?<=[0-9A-Za-z])(?=[А-Яа-яЁё])',' ',value)
  if isinstance(value,list):return [tidy(x) for x in value]
  if isinstance(value,dict):return {k:tidy(v) for k,v in value.items()}
  return value
 B.ex=tidy(B.ex);B.models=tidy(B.models)
 B.write()
